INSERT INTO `ws_gads_lps` (`page_title`, `page_name`, `page_status`, `page_description`, `page_og_image`, `page_schema`, `page_data`, `page_hero_image`, `page_date`) VALUES ('Crédito Agrícola para Pequeno Produtor na Serra Gaúcha — ICC Serra', 'credito-agricola', '1', 'Crédito agrícola para pequeno produtor e agricultura familiar na Serra Gaúcha. Compra ou conserto de máquina, custeio de safra. ICC Serra — Banco do Povo.', 'https://iccserra.org.br/assets/og-credito-agricola.jpg', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FinancialProduct\",\n    \"name\": \"Crédito Agrícola ICC Serra\",\n    \"description\": \"Crédito para pequeno produtor rural e agricultura familiar na Serra Gaúcha. Compra ou conserto de máquinas, custeio de safra.\",\n    \"provider\": {\n      \"@type\": \"Organization\",\n      \"name\": \"ICC Serra — Banco do Povo\",\n      \"url\": \"https://iccserra.org.br\",\n      \"telephone\": \"+55-54-3217-8787\",\n      \"email\": \"iccserra@iccserra.org.br\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Rua Pinheiro Machado, 1707\",\n        \"addressLocality\": \"Caxias do Sul\",\n        \"addressRegion\": \"RS\",\n        \"addressCountry\": \"BR\"\n      }\n    },\n    \"loanType\": \"Microcrédito Produtivo Orientado — Linha Agrícola\",\n    \"currency\": \"BRL\",\n    \"amount\": {\n      \"@type\": \"MonetaryAmount\",\n      \"minValue\": 600,\n      \"maxValue\": 20000,\n      \"currency\": \"BRL\"\n    },\n    \"areaServed\": {\n      \"@type\": \"State\",\n      \"name\": \"Rio Grande do Sul\"\n    }\n  }', '{\"theme\":\"\",\"nav_label\":\"Agrícola\",\"header_cta\":\"Simular crédito\",\"hero\":{\"pill\":\"Para o pequeno produtor da Serra Gaúcha que precisa de crédito para tocar a lavoura\",\"title\":\"Crédito agrícola que olha a sua safra, não só o seu cadastro\",\"subtitle\":\"A ICC Serra — Banco do Povo — tem agente que vai até a sua propriedade. Para comprar ou consertar máquina, custear a safra, ou investir no que a lavoura precisa. De R$ 600 a R$ 20 mil. Taxa fixa. Sem IOF.\",\"cta\":\"Simular crédito agrícola\",\"cta2\":\"\",\"microcopy\":\"Leva 2 minutos. Um agente fala com você em até 24 horas.\",\"img_alt\":\"Pequeno produtor rural atendido pela ICC Serra na Serra Gaúcha\"},\"trust\":[{\"icon\":\"🏛️\",\"text\":\"OSCIP do Ministério da Justiça\"},{\"icon\":\"🌾\",\"text\":\"Agente vai à propriedade\"},{\"icon\":\"📅\",\"text\":\"25 anos no Banco do Povo\"},{\"icon\":\"✅\",\"text\":\"Sem IOF\"}],\"pains\":{\"title\":\"Se uma dessas situações está na sua lavoura agora:\",\"items\":[\"\\\"O trator quebrou na semana errada.\\\"\",\"\\\"A safra está chegando e o caixa não cobre o custeio.\\\"\",\"\\\"Pedi no banco e não consegui — ou o processo demorou demais.\\\"\",\"\\\"Quero trocar o implemento, mas não sobra dinheiro depois que pago o arrendamento.\\\"\",\"\\\"Tenho terra mas não tenho garantia para o banco.\\\"\",\"\\\"Quero fechar o ano no azul, não no sufoco.\\\"\"],\"transition\":\"Banco grande não entende o ritmo da safra. A gente entende. E o agente vai até você para ouvir.\",\"cta\":\"Ver quanto posso pegar\"},\"steps\":{\"title\":\"Como funciona o Crédito Olho no Olho — linha Agrícola\",\"items\":[{\"title\":\"Conta sua ideia\",\"desc\":\"Você preenche o formulário em 2 minutos — nome, WhatsApp, cidade, o que precisa na lavoura. Nenhum documento nesse momento.\"},{\"title\":\"Agente vai até você\",\"desc\":\"Um agente de crédito da ICC da sua região entra em contato e marca visita na propriedade. Ele entende de onde vem a renda, qual é o calendário da safra, qual o custo do que você precisa comprar ou consertar. Essa conversa é o que define o crédito — não um formulário impessoal.\"},{\"title\":\"Crédito que cabe na safra\",\"desc\":\"A parcela é ajustada ao que o seu caixa agrícola aguenta. De R$ 600 a R$ 20 mil, de 3 a 24 meses, taxa fixa de até 3,99% a.m., sem IOF. Planejado para não comprometer o ano.\"}]},\"line\":{\"tag\":\"Crédito Agrícola ICC Serra\",\"title\":\"O que você precisa saber\",\"who_title\":\"Quem pode pedir\",\"who\":[\"Pequeno produtor rural (proprietário, arrendatário ou parceiro)\",\"Agricultor familiar — viticultor, fruticultor, leiteiro, olericultor\",\"Produtor de uva, maçã, leite, hortaliças, grãos em pequena escala\",\"Produtor com ou sem DAP/CAF\"],\"use_title\":\"Para que serve\",\"use\":[\"Comprar máquina agrícola usada ou nova (trator, colheitadeira, pulverizador)\",\"Consertar equipamento parado — não perder a safra\",\"Comprar implemento (arado, grade, carreta)\",\"Custear a safra: adubo, muda, defensivo, combustível\",\"Reformar galpão ou estrutura de armazenagem\",\"Comprar animais para produção (leite, suíno)\"],\"use_text\":\"\",\"docs\":[\"RG ou CNH\",\"CPF\",\"Comprovante de endereço\",\"Documento de atividade rural: nota fiscal de venda, contrato de arrendamento, DAP/CAF (se tiver), CCIR da propriedade ou declaração de produtor\"],\"docs_note\":\"Produtor rural informal sem DAP/CAF pode ser atendido — confirmar com o agente da sua cidade. Documentação sujeita a validação operacional antes da publicação.\",\"prazo\":\"em média 5 a 10 dias úteis após a visita do agente para liberação do crédito.\",\"cond_title\":\"Condições do crédito\",\"cond\":[{\"value\":\"R$ 600 – R$ 20.000\",\"label\":\"Valor disponível\",\"badge\":\"\"},{\"value\":\"3 – 24 meses\",\"label\":\"Prazo de pagamento\",\"badge\":\"\"},{\"value\":\"Até 3,99% a.m.\",\"label\":\"Taxa de juros fixa (56,45% a.a.)\",\"badge\":\"\"},{\"value\":\"Sem IOF\",\"label\":\"Operação isenta de IOF\",\"badge\":\"Diferencial\"},{\"value\":\"Parcela ajustada\",\"label\":\"Calculada no ciclo da sua safra\",\"badge\":\"\"}],\"cta\":\"Simular crédito agrícola\"},\"proof\":{\"tag\":\"Por que confiar\",\"title\":\"Por que confiar na ICC Serra?\",\"cards\":[{\"icon\":\"🏛️\",\"title\":\"OSCIP qualificada pelo Ministério da Justiça\",\"text\":\"Não somos banco comercial, não somos financeira. Somos uma instituição comunitária sem fins lucrativos reconhecida pelo governo federal.\"},{\"icon\":\"📅\",\"title\":\"25 anos na Serra Gaúcha\",\"text\":\"Desde 2001 atendendo produtores e empreendedores da região. Quem trabalha com a terra aqui conhece o Banco do Povo.\"},{\"icon\":\"🚜\",\"title\":\"Agente vai até a propriedade\",\"text\":\"Você não precisa largar a lavoura para ir ao escritório. O agente vai até você, na sua propriedade, no horário que dá.\"},{\"icon\":\"🏦\",\"title\":\"Convênio com o BRDE\",\"text\":\"A ICC Serra tem parceria com o Banco Regional de Desenvolvimento do Extremo Sul para ampliar o crédito para o pequeno produtor.\"},{\"icon\":\"📍\",\"title\":\"13+ pontos no RS — perto da lavoura\",\"text\":\"Caxias do Sul, Bento Gonçalves, Farroupilha, Garibaldi, Veranópolis, Vacaria, Marau, Lajeado. Cobertura da Serra ao Vale.\"}],\"testi_title\":\"O que dizem os produtores atendidos\",\"testi\":[{\"text\":\"O trator quebrou no meio da vindima. Liguei pra ICC, o agente foi até a propriedade no dia seguinte. Em três dias o dinheiro estava na conta. Consegui alugar a máquina e não perdi a safra.\",\"author\":\"Valdir Girardi\",\"meta\":\"Viticultor — Bento Gonçalves\"},{\"text\":\"Banco me pediu garantia que eu não tenho. Na ICC o agente veio ver a lavoura, conversou com a família. O crédito pagou as mudas e o adubo. Essa safra foi a melhor dos últimos anos.\",\"author\":\"Neri Cecchin\",\"meta\":\"Agricultor familiar — Veranópolis\"},{\"text\":\"Plantava hortaliça no quintal e vendia na feirinha. Com o crédito comprei uma estufa simples. Agora vendo pra dois mercados da cidade. O agente me ajudou a encaixar a parcela no ritmo da colheita.\",\"author\":\"Darci Pereira\",\"meta\":\"Horticultora — Carlos Barbosa\"}]},\"faq\":{\"title\":\"Perguntas que o produtor faz antes de solicitar\",\"items\":[{\"q\":\"Sou arrendatário, não tenho terra própria. Posso pedir?\",\"a\":\"Sim. A ICC analisa a atividade agrícola que você exerce, não a titularidade da terra. Arrendatário, parceiro ou meeiro que toca a lavoura pode solicitar.\",\"cta\":\"\",\"open\":true},{\"q\":\"Já tentei Pronaf e não me encaixei. Isso funciona diferente?\",\"a\":\"Sim. A ICC Serra é uma OSCIP de microcrédito produtivo orientado — o processo é mais ágil e a análise é feita pelo agente direto com você, sem as exigências técnicas do crédito rural oficial. Muitos produtores que não se encaixam no Pronaf conseguem crédito aqui.\",\"cta\":\"\",\"open\":true},{\"q\":\"Vou ter que ir até o escritório da ICC?\",\"a\":\"Não. Você preenche o formulário em 2 minutos e o agente é que vai até a sua propriedade. Você não precisa largar o que está fazendo.\",\"cta\":\"Simular agora →\",\"open\":false},{\"q\":\"A taxa não é alta para crédito agrícola?\",\"a\":\"A taxa máxima é de 3,99% ao mês, fixa, sem IOF. O prazo chega a 24 meses e a parcela é calculada no que o seu caixa agrícola aguenta. Faz sentido comparar com o custo de alugar equipamento ou perder safra por falta de conserto.\",\"cta\":\"\",\"open\":false},{\"q\":\"A ICC Serra conhece a realidade do pequeno produtor?\",\"a\":\"Sim. Está na Serra Gaúcha desde 2001 — em Bento Gonçalves, Garibaldi, Veranópolis, Vacaria, Marau e outras cidades de produção. O agente que vai até você é da região, conhece o ciclo das culturas locais.\",\"cta\":\"\",\"open\":false},{\"q\":\"Quanto tempo demora para o dinheiro cair?\",\"a\":\"Em média 5 a 10 dias úteis depois da visita do agente. Mais rápido do que crédito rural via banco, na maioria dos casos.\",\"cta\":\"Ver meu prazo — simular agora →\",\"open\":false}]},\"final\":{\"title\":\"O Banco do Povo não pergunta o que você tem. Pergunta o que a sua lavoura precisa.\",\"text\":\"Você sabe o que a safra precisa. Sabe o que está parado e o que custaria consertar. Agora você tem um crédito com agente que vai até a sua propriedade, parcela que cabe no que o ano produz, e 25 anos de Banco do Povo como garantia de que funciona.\\n\\nConta o que a lavoura precisa. Dois minutos.\",\"cta\":\"Solicitar Crédito Agrícola\"},\"legal\":\"Microcrédito produtivo orientado — linha Agrícola. Taxa de juros: até 3,99% a.m. (56,45% a.a.). Valores: de R$ 600,00 a R$ 20.000,00. Prazo: de 3 a 24 meses. Operação isenta de IOF. Sujeito à análise de crédito. As condições podem variar conforme perfil e finalidade. Consulte o agente da sua cidade.\",\"wa_text\":\"Olá! Quero saber sobre o Crédito Agrícola da ICC Serra.\"}', 'images/importadas/microcredito.webp', '2026-11-23 23:32:23')
ON DUPLICATE KEY UPDATE `page_title` = VALUES(`page_title`), `page_description` = VALUES(`page_description`), `page_og_image` = VALUES(`page_og_image`), `page_schema` = VALUES(`page_schema`), `page_data` = VALUES(`page_data`), `page_hero_image` = VALUES(`page_hero_image`);

INSERT INTO `ws_gads_lps` (`page_title`, `page_name`, `page_status`, `page_description`, `page_og_image`, `page_schema`, `page_data`, `page_hero_image`, `page_date`) VALUES ('Crédito para Reformar ou Ampliar sua Loja — ICC Serra Banco do Povo', 'credito-reforma-ampliacao', '1', 'Crédito para reformar loja, oficina ou negócio na Serra Gaúcha. ICC Serra — Banco do Povo. Agente vai até você. R$ 600 a R$ 20 mil. Sem IOF.', 'https://iccserra.org.br/assets/og-credito-reforma.jpg', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FinancialProduct\",\n    \"name\": \"Crédito para Reforma ou Ampliação — ICC Serra\",\n    \"description\": \"Crédito para reformar loja, oficina ou espaço comercial na Serra Gaúcha. Agente vai até o espaço.\",\n    \"provider\": {\n      \"@type\": \"Organization\",\n      \"name\": \"ICC Serra — Banco do Povo\",\n      \"url\": \"https://iccserra.org.br\",\n      \"telephone\": \"+55-54-3217-8787\",\n      \"email\": \"iccserra@iccserra.org.br\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Rua Pinheiro Machado, 1707\",\n        \"addressLocality\": \"Caxias do Sul\",\n        \"addressRegion\": \"RS\",\n        \"addressCountry\": \"BR\"\n      }\n    },\n    \"loanType\": \"Microcrédito Produtivo Orientado — Linha Reforma e Ampliação\",\n    \"currency\": \"BRL\",\n    \"amount\": {\n      \"@type\": \"MonetaryAmount\",\n      \"minValue\": 600,\n      \"maxValue\": 20000,\n      \"currency\": \"BRL\"\n    },\n    \"areaServed\": {\n      \"@type\": \"State\",\n      \"name\": \"Rio Grande do Sul\"\n    }\n  }', '{\"theme\":\"\",\"nav_label\":\"Reforma\",\"header_cta\":\"Simular crédito\",\"hero\":{\"pill\":\"Para o dono de loja ou oficina que já sabe o que quer fazer — só falta o capital\",\"title\":\"Crédito para reformar ou ampliar seu negócio, com parcela que cabe no caixa\",\"subtitle\":\"A ICC Serra — Banco do Povo — tem agente que vai até o seu espaço, entende o que você precisa, e libera de R$ 600 a R$ 20 mil com taxa fixa, sem IOF e sem burocracia de banco grande. Pintura, ampliação, ar-condicionado, letreiro, reforma de banheiro — o crédito é para o que o seu negócio precisa.\",\"cta\":\"Simular crédito para reforma\",\"cta2\":\"\",\"microcopy\":\"Leva 2 minutos. Um agente da sua cidade fala com você em até 24 horas.\",\"img_alt\":\"Dono de negócio planejando reforma com apoio da ICC Serra\"},\"trust\":[{\"icon\":\"🏛️\",\"text\":\"OSCIP do Ministério da Justiça\"},{\"icon\":\"🏗️\",\"text\":\"Crédito para reforma comercial\"},{\"icon\":\"📅\",\"text\":\"25 anos no Banco do Povo\"},{\"icon\":\"✅\",\"text\":\"Sem IOF\"}],\"pains\":{\"title\":\"Se uma dessas frases já passou pela sua cabeça:\",\"items\":[\"\\\"A loja está precisando de pintura, mas não dá pra tirar do caixa agora.\\\"\",\"\\\"Eu sei exatamente o que quero fazer — só não tenho o dinheiro à vista.\\\"\",\"\\\"Quero ampliar pra atender mais cliente, mas o espaço está pequeno.\\\"\",\"\\\"Banco não me deu crédito para reforma — falaram que não é finalidade deles.\\\"\",\"\\\"Se eu reformar, vendo mais. Mas sem vender mais, não reformo.\\\"\",\"\\\"Já juntei parte do dinheiro, preciso de um complemento.\\\"\"],\"transition\":\"Você tem a ideia e conhece o espaço. O que faltava era um crédito com agente que fosse até lá entender o que você precisa. Agora tem.\",\"cta\":\"Ver quanto posso pegar para a reforma\"},\"steps\":{\"title\":\"Como funciona o Crédito Olho no Olho — linha Reforma e Ampliação\",\"items\":[{\"title\":\"Conta sua ideia\",\"desc\":\"Você preenche o formulário em 2 minutos — nome, WhatsApp, cidade, o que quer reformar ou ampliar. Sem nenhum documento nesse momento.\"},{\"title\":\"Agente vai até o seu espaço\",\"desc\":\"Um agente de crédito da ICC da sua cidade marca visita na sua loja, oficina ou negócio. Ele vê o espaço, conversa sobre a reforma, entende o custo e a finalidade. A análise considera o movimento do negócio — não só o extrato do banco.\"},{\"title\":\"Crédito que cabe no caixa\",\"desc\":\"A parcela é calculada para não comprometer o movimento do mês. De R$ 600 a R$ 20 mil, de 3 a 24 meses, taxa fixa de até 3,99% a.m., sem IOF. Reforma feita, parcela controlada.\"}]},\"line\":{\"tag\":\"Crédito para Reforma ou Ampliação\",\"title\":\"O que você precisa saber\",\"who_title\":\"Quem pode pedir\",\"who\":[\"MEI ou microempresário com negócio físico (loja, oficina, salão, restaurante, mercadinho, ateliê)\",\"Autônomo que trabalha em espaço próprio ou alugado\",\"Informal com atividade comprovada\"],\"use_title\":\"Para que serve\",\"use\":[\"Pintura, revestimento, piso — atualizar a aparência do espaço\",\"Ampliação de área — derrubar parede, abrir espaço novo, cobrir área externa\",\"Instalação de ar-condicionado, ventilação, elétrica\",\"Troca de letreiro, fachada, vitrine\",\"Reforma de banheiro, cozinha ou área de atendimento\",\"Instalação de câmera, balcão, prateleiras\",\"Adequação para acessibilidade ou vigilância sanitária\"],\"use_text\":\"\",\"docs\":[\"RG ou CNH\",\"CPF\",\"Comprovante de endereço\",\"Para MEI: CCMEI\",\"Para informal: nota de compra, foto do negócio ou declaração de cliente\",\"Orçamento da reforma (se tiver — ajuda na análise, mas não é obrigatório para solicitar)\"],\"docs_note\":\"Documentação confirmada com a área de operações antes da publicação. Condições sujeitas a alteração.\",\"prazo\":\"em média 5 a 10 dias úteis após a visita do agente para liberação do crédito.\",\"cond_title\":\"Condições do crédito\",\"cond\":[{\"value\":\"R$ 600 – R$ 20.000\",\"label\":\"Valor disponível\",\"badge\":\"\"},{\"value\":\"3 – 24 meses\",\"label\":\"Prazo de pagamento\",\"badge\":\"\"},{\"value\":\"Até 3,99% a.m.\",\"label\":\"Taxa de juros fixa (56,45% a.a.)\",\"badge\":\"\"},{\"value\":\"Sem IOF\",\"label\":\"Operação isenta de IOF\",\"badge\":\"Diferencial\"},{\"value\":\"Parcela ajustada\",\"label\":\"Calculada no movimento do negócio\",\"badge\":\"\"}],\"cta\":\"Simular crédito para reforma\"},\"proof\":{\"tag\":\"Por que confiar\",\"title\":\"Por que confiar na ICC Serra?\",\"cards\":[{\"icon\":\"🏛️\",\"title\":\"OSCIP qualificada pelo Ministério da Justiça\",\"text\":\"Não somos financeira. Somos uma instituição comunitária sem fins lucrativos, reconhecida pelo governo federal desde 2001.\"},{\"icon\":\"📅\",\"title\":\"25 anos no Banco do Povo da Serra Gaúcha\",\"text\":\"Quem reformou a loja com a gente, voltou pra crescer mais. Quem voltou, indicou.\"},{\"icon\":\"🔍\",\"title\":\"Agente vai até o seu espaço\",\"text\":\"Ele vê o que precisa ser feito. A análise começa do lugar real, não de um formulário frio.\"},{\"icon\":\"🏗️\",\"title\":\"Crédito para finalidade que banco recusa\",\"text\":\"Reforma de espaço comercial não é prioridade de banco grande. Aqui é exatamente para isso que o crédito existe.\"},{\"icon\":\"📍\",\"title\":\"13+ pontos no RS — perto da sua loja\",\"text\":\"Caxias do Sul, Bento Gonçalves, Farroupilha, Garibaldi, Vacaria, Veranópolis, Lajeado, Marau e mais.\"}],\"testi_title\":\"O que dizem quem já reformou com a ICC\",\"testi\":[{\"text\":\"A fachada estava velha, afastava cliente. Peguei crédito na ICC pra pintar, botar letreiro novo e renovar o balcão. Em dois meses o movimento aumentou. O visual faz diferença — e o agente me disse isso antes.\",\"author\":\"Eduardo Zanella\",\"meta\":\"Dono de açougue — Farroupilha\"},{\"text\":\"Queria ampliar o salão pra colocar mais uma cadeira. O banco pediu documentação enorme e demorou semanas. Na ICC foi mais simples: o agente veio conhecer o salão e liberou em uma semana.\",\"author\":\"Camila Rigon\",\"meta\":\"Cabeleireira, dona de salão — Caxias do Sul\"},{\"text\":\"Reformei a cozinha e coloquei ar-condicionado antes da temporada de inverno. O crédito da ICC me salvou. Parcelei em 18 meses, coube tranquilo no caixa. Foi o melhor investimento que fiz na loja.\",\"author\":\"Marcos Grazziotin\",\"meta\":\"Dono de lanchonete — Gramado\"}]},\"faq\":{\"title\":\"Perguntas comuns antes de solicitar\",\"items\":[{\"q\":\"Banco disse que não financia reforma. A ICC faz isso?\",\"a\":\"Sim. O Crédito para Reforma e Ampliação existe exatamente para isso — é uma das 5 linhas da ICC Serra. É uma das finalidades mais comuns de solicitação.\",\"cta\":\"\",\"open\":true},{\"q\":\"Preciso ter orçamento da reforma antes de solicitar?\",\"a\":\"Não precisa ter na hora do formulário. O agente vai até o seu espaço e conversa sobre o que precisa ser feito. Se você já tiver um orçamento, ajuda na definição do valor — mas não é exigência para começar.\",\"cta\":\"Simular agora →\",\"open\":false},{\"q\":\"Não tenho CNPJ. Posso pedir mesmo assim?\",\"a\":\"Sim. A ICC atende MEI formalizado e também informal. O que importa é ter um negócio funcionando e precisar da reforma para ele.\",\"cta\":\"\",\"open\":false},{\"q\":\"A taxa é alta?\",\"a\":\"A taxa máxima é de 3,99% ao mês, fixa, sem IOF. O prazo chega a 24 meses. Uma reforma que aumenta o faturamento em R$ 500 por mês paga a parcela sem comprometer o negócio.\",\"cta\":\"\",\"open\":false},{\"q\":\"Vou precisar ir até a ICC várias vezes?\",\"a\":\"Não. Você preenche o formulário online em 2 minutos. O agente que vai até você — na sua loja, no horário que funcionar melhor.\",\"cta\":\"\",\"open\":false},{\"q\":\"Posso reformar e também comprar equipamento com o mesmo crédito?\",\"a\":\"Sim. O crédito pode ser usado tanto para reforma do espaço quanto para compra de equipamentos que ficam fixos no negócio. Conta o que você precisa e o agente orienta sobre o que entra na linha.\",\"cta\":\"Simular agora →\",\"open\":false}]},\"final\":{\"title\":\"O Banco do Povo não pergunta o que você tem. Pergunta o que você quer construir.\",\"text\":\"Você sabe o que a loja precisa. Sabe o que está faltando para atender melhor. Agora tem um crédito com agente que vai até o espaço, parcela que cabe no caixa, e 25 anos de Banco do Povo garantindo que funciona.\\n\\nConta o que você quer reformar. Dois minutos.\",\"cta\":\"Solicitar crédito para reforma\"},\"legal\":\"Microcrédito produtivo orientado — linha Reforma e Ampliação. Taxa de juros: até 3,99% a.m. (56,45% a.a.). Valores: de R$ 600,00 a R$ 20.000,00. Prazo: de 3 a 24 meses. Operação isenta de IOF. Sujeito à análise de crédito. As condições podem variar conforme perfil e finalidade. Consulte o agente da sua cidade.\",\"wa_text\":\"Olá! Quero saber sobre o Crédito para Reforma ou Ampliação da ICC Serra.\"}', 'images/importadas/credito-para-reforma-ou-ampliacao-1503399105.jpg', '2026-11-23 23:32:23')
ON DUPLICATE KEY UPDATE `page_title` = VALUES(`page_title`), `page_description` = VALUES(`page_description`), `page_og_image` = VALUES(`page_og_image`), `page_schema` = VALUES(`page_schema`), `page_data` = VALUES(`page_data`), `page_hero_image` = VALUES(`page_hero_image`);

INSERT INTO `ws_gads_lps` (`page_title`, `page_name`, `page_status`, `page_description`, `page_og_image`, `page_schema`, `page_data`, `page_hero_image`, `page_date`) VALUES ('Microcrédito Mulher — Crédito para Empreendedora na Serra Gaúcha — ICC Serra', 'microcredito-mulher', '1', 'Microcrédito para mulher empreendedora na Serra Gaúcha. Linha exclusiva da ICC Serra. Agente vai até você. R$ 600 a R$ 20 mil. Sem IOF.', 'https://iccserra.org.br/assets/og-microcredito-mulher.jpg', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FinancialProduct\",\n    \"name\": \"Microcrédito Mulher\",\n    \"description\": \"Linha de microcrédito produtivo orientado exclusiva para mulheres empreendedoras da Serra Gaúcha.\",\n    \"provider\": {\n      \"@type\": \"Organization\",\n      \"name\": \"ICC Serra — Banco do Povo\",\n      \"url\": \"https://iccserra.org.br\",\n      \"telephone\": \"+55-54-3217-8787\",\n      \"email\": \"iccserra@iccserra.org.br\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Rua Pinheiro Machado, 1707\",\n        \"addressLocality\": \"Caxias do Sul\",\n        \"addressRegion\": \"RS\",\n        \"addressCountry\": \"BR\"\n      }\n    },\n    \"loanType\": \"Microcrédito Produtivo Orientado — Linha Mulher\",\n    \"currency\": \"BRL\",\n    \"amount\": {\n      \"@type\": \"MonetaryAmount\",\n      \"minValue\": 600,\n      \"maxValue\": 20000,\n      \"currency\": \"BRL\"\n    },\n    \"areaServed\": {\n      \"@type\": \"State\",\n      \"name\": \"Rio Grande do Sul\"\n    }\n  }', '{\"theme\":\"mulher\",\"nav_label\":\"Mulher\",\"header_cta\":\"Simular crédito\",\"hero\":{\"pill\":\"Para a mulher que já construiu seu negócio — e quer ir além\",\"title\":\"Microcrédito Mulher: crédito que olha o que você já fez, não o que você ainda não tem\",\"subtitle\":\"A ICC Serra criou uma linha de crédito pensada pra quem empreende com as próprias mãos — da costureira à confeiteira, da manicure à vendedora de feira. Agente vai até você. De R$ 600 a R$ 20 mil, com parcela que cabe no caixa. Sem IOF.\",\"cta\":\"Simular meu crédito agora\",\"cta2\":\"\",\"microcopy\":\"Leva 2 minutos. Um agente da sua cidade fala com você em até 24 horas.\",\"img_alt\":\"Mulher empreendedora atendida pela ICC Serra no seu próprio negócio\"},\"trust\":[{\"icon\":\"🏛️\",\"text\":\"OSCIP do Ministério da Justiça\"},{\"icon\":\"👩\",\"text\":\"Linha criada para mulheres\"},{\"icon\":\"📍\",\"text\":\"13+ pontos no RS\"},{\"icon\":\"✅\",\"text\":\"Sem IOF\"}],\"pains\":{\"title\":\"Se você já pensou alguma dessas coisas, este crédito foi feito pra você:\",\"items\":[\"\\\"Banco não olha pra gente.\\\"\",\"\\\"Quero comprar uma máquina nova pra produzir mais, mas não tenho como tirar do caixa agora.\\\"\",\"\\\"Trabalho o dia todo e ainda não consegui guardar o suficiente pra crescer.\\\"\",\"\\\"Não tenho CNPJ, não sei se consigo.\\\"\",\"\\\"Quero ter o meu próprio dinheiro — não depender de ninguém.\\\"\",\"\\\"Tô no zero a zero todo mês. Quero sair disso.\\\"\"],\"transition\":\"Você tem o negócio. Tem o trabalho. Tem a ideia. O que faltava era um crédito que entendesse isso tudo. Agora tem.\",\"cta\":\"Ver quanto posso pegar\"},\"steps\":{\"title\":\"Como funciona o Crédito Olho no Olho — linha Mulher\",\"items\":[{\"title\":\"Conta sua ideia\",\"desc\":\"Você preenche o formulário agora, em 2 minutos. Nome, WhatsApp, cidade, o que precisa. Nada de papel ainda.\"},{\"title\":\"Agente vai até você\",\"desc\":\"Um agente de crédito da ICC da sua cidade entra em contato pelo WhatsApp e marca a visita — na sua casa, no seu salão, na sua cozinha. Ela vai entender o seu negócio do jeito que ele é, não do jeito que o banco queria que fosse.\"},{\"title\":\"Crédito que cabe\",\"desc\":\"A parcela é calculada para caber no que seu caixa aguenta. De R$ 600 a R$ 20 mil, de 3 a 24 meses, taxa fixa, sem IOF. Sem surpresa.\"}]},\"line\":{\"tag\":\"Microcrédito Mulher\",\"title\":\"Tudo que você precisa saber antes de pedir\",\"who_title\":\"Quem pode pedir\",\"who\":[\"Mulher empreendedora — formal (MEI) ou informal\",\"Costureira, manicure, cabeleireira, confeiteira, vendedora de marmita\",\"Feirante, sacoleira, artesã\",\"Qualquer mulher que sustenta ou complementa a renda com trabalho próprio\"],\"use_title\":\"Para que serve\",\"use\":[\"Comprar máquina de costura, forno, equipamento de estética\",\"Comprar mercadoria para ampliar o estoque\",\"Ter capital de giro para não ficar no sufoco no meio do mês\",\"Montar ou melhorar o espaço de trabalho em casa\",\"Pagar fornecedor sem precisar do cartão\"],\"use_text\":\"\",\"docs\":[\"RG ou CNH\",\"CPF\",\"Comprovante de endereço recente\",\"Para MEI: CCMEI\",\"Para informal: nota de compra, foto do negócio ou indicação de cliente\"],\"docs_note\":\"Documentação confirmada com a área de operações antes da publicação. Condições sujeitas a alteração.\",\"prazo\":\"em média 5 a 10 dias úteis após a visita da agente para liberação do crédito.\",\"cond_title\":\"Condições do crédito\",\"cond\":[{\"value\":\"R$ 600 – R$ 20.000\",\"label\":\"Valor disponível\",\"badge\":\"\"},{\"value\":\"3 – 24 meses\",\"label\":\"Prazo de pagamento\",\"badge\":\"\"},{\"value\":\"Até 3,99% a.m.\",\"label\":\"Taxa de juros fixa (56,45% a.a.)\",\"badge\":\"\"},{\"value\":\"Sem IOF\",\"label\":\"Operação isenta de IOF\",\"badge\":\"Diferencial\"},{\"value\":\"Parcela ajustada\",\"label\":\"Calculada no que seu caixa suporta\",\"badge\":\"\"}],\"cta\":\"Simular meu crédito agora\"},\"proof\":{\"tag\":\"Por que confiar\",\"title\":\"Por que confiar na ICC Serra?\",\"cards\":[{\"icon\":\"🏛️\",\"title\":\"OSCIP qualificada pelo Ministério da Justiça\",\"text\":\"Instituição comunitária sem fins lucrativos. Reconhecida pelo governo federal. Não é financeira, não é agiota.\"},{\"icon\":\"📅\",\"title\":\"25 anos atendendo quem o banco esqueceu\",\"text\":\"Desde 2001 no Banco do Povo da Serra Gaúcha. Quem foi atendido, voltou. Quem voltou, indicou.\"},{\"icon\":\"👩‍💼\",\"title\":\"Linha criada para mulheres empreendedoras\",\"text\":\"Não é o crédito genérico adaptado. É uma linha pensada pra quem trabalha, muitas vezes, sem horário fixo e sem contrato assinado.\"},{\"icon\":\"🤝\",\"title\":\"Agente de crédito humano — da sua cidade\",\"text\":\"Não um app. Uma pessoa. Que vai até você, ouve você, entende o que você está construindo.\"},{\"icon\":\"📍\",\"title\":\"13+ pontos no RS\",\"text\":\"Caxias do Sul, Bento Gonçalves, Farroupilha, Garibaldi, Vacaria, Veranópolis, Lajeado, Marau e outros. Sempre perto.\"}],\"testi_title\":\"O que dizem quem já foi atendida\",\"testi\":[{\"text\":\"Precisava trocar a máquina de overloque — a antiga quebrava todo dia. Fui na ICC, a atendente foi super atenciosa. Em uma semana tinha o crédito na conta. Agora atendo o dobro de clientes.\",\"author\":\"Andréia Fontanive\",\"meta\":\"Costureira autônoma — Garibaldi\"},{\"text\":\"Sustentei meus filhos anos vendendo bolo. Achei que banco nenhum ia me dar crédito. A ICC olhou minha realidade, não o meu Serasa. Comprei a batedeira planetária e dobrei o faturamento no Natal.\",\"author\":\"Juliana Prezotto\",\"meta\":\"Confeiteira autônoma — Caxias do Sul\"},{\"text\":\"Precisava de capital de giro pro inverno — coleção nova, frete, tudo junto. O agente veio na loja, entendeu meu ciclo de estoque. A parcela coube no caixa e não quebrei na baixa temporada.\",\"author\":\"Patrícia Rech\",\"meta\":\"Dona de boutique infantil — Bento Gonçalves\"}]},\"faq\":{\"title\":\"Perguntas que toda empreendedora faz antes de solicitar\",\"items\":[{\"q\":\"Trabalho em casa e não sou MEI. Posso pedir?\",\"a\":\"Sim. A ICC Serra atende mulheres que trabalham de forma informal — de casa, na rua, na feira, em salão alugado por hora. O que importa é o trabalho que você faz, não um papel de registro.\",\"cta\":\"\",\"open\":false},{\"q\":\"Tenho um score baixo no Serasa. Ainda assim tenho chance?\",\"a\":\"Ter score baixo não é eliminatório aqui. O agente analisa o seu negócio real — as vendas, os clientes, a movimentação. Muita gente com score restrito tem crédito aprovado porque o negócio é consistente.\",\"cta\":\"\",\"open\":false},{\"q\":\"Vou precisar sair do trabalho para ir até a ICC?\",\"a\":\"Não. Você faz o formulário em 2 minutos e o agente é que vai até você. A visita acontece no horário que funciona pra você — na sua loja, no seu salão, na sua casa.\",\"cta\":\"Simular agora →\",\"open\":false},{\"q\":\"A parcela vai me sufocar?\",\"a\":\"A parcela é calculada com base no que o seu negócio movimenta. Antes de liberar, o agente entende o seu caixa e propõe uma parcela que não vai comprometer o mês. Esse é o diferencial da análise orientada.\",\"cta\":\"\",\"open\":false},{\"q\":\"A ICC Serra é de confiança? Como eu sei que é sério?\",\"a\":\"A ICC Serra existe desde 2001 — são 25 anos como Banco do Povo na Serra Gaúcha. É uma OSCIP qualificada pelo Ministério da Justiça, com 13+ postos físicos no RS. Você pode ligar antes de preencher qualquer coisa: 54 3217-8787.\",\"cta\":\"\",\"open\":false},{\"q\":\"Quanto demora para o crédito sair?\",\"a\":\"Em média 5 a 10 dias úteis depois da visita da agente. Bem diferente de semanas esperando um retorno de banco grande.\",\"cta\":\"Simular agora →\",\"open\":false}]},\"final\":{\"title\":\"O Banco do Povo não pergunta o que você tem. Pergunta o que você quer construir.\",\"text\":\"Você já provou que sabe trabalhar. Agora precisa de capital para ir além. A ICC Serra tem agente que vai até você, taxa fixa, parcela no que o seu caixa aguenta — e 25 anos de Banco do Povo como garantia de que funciona.\\n\\nConta sua ideia. Dois minutos.\",\"cta\":\"Solicitar Microcrédito Mulher\"},\"legal\":\"Microcrédito produtivo orientado — linha Mulher. Taxa de juros: até 3,99% a.m. (56,45% a.a.). Valores: de R$ 600,00 a R$ 20.000,00. Prazo: de 3 a 24 meses. Operação isenta de IOF. Sujeito à análise de crédito. As condições podem variar conforme perfil e finalidade. Consulte o agente da sua cidade.\",\"wa_text\":\"Olá! Quero saber sobre o Microcrédito Mulher da ICC Serra.\"}', 'images/importadas/microcredito-mulher-1627067535.png', '2026-11-23 23:32:23')
ON DUPLICATE KEY UPDATE `page_title` = VALUES(`page_title`), `page_description` = VALUES(`page_description`), `page_og_image` = VALUES(`page_og_image`), `page_schema` = VALUES(`page_schema`), `page_data` = VALUES(`page_data`), `page_hero_image` = VALUES(`page_hero_image`);

INSERT INTO `ws_gads_lps` (`page_title`, `page_name`, `page_status`, `page_description`, `page_og_image`, `page_schema`, `page_data`, `page_hero_image`, `page_date`) VALUES ('Microcrédito Produtivo em Caxias do Sul e Serra Gaúcha — ICC Serra', 'microcredito-produtivo', '1', 'Microcrédito produtivo para MEI, autônomo e informal na Serra Gaúcha. Agente vai até você. R$ 600 a R$ 20 mil. Sem IOF. ICC Serra — Banco do Povo.', 'https://iccserra.org.br/assets/og-microcredito-produtivo.jpg', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FinancialProduct\",\n    \"name\": \"Microcrédito Produtivo\",\n    \"description\": \"Microcrédito produtivo orientado para MEI, autônomos e informais da Serra Gaúcha. Agente vai até você.\",\n    \"provider\": {\n      \"@type\": \"Organization\",\n      \"name\": \"ICC Serra — Banco do Povo\",\n      \"url\": \"https://iccserra.org.br\",\n      \"telephone\": \"+55-54-3217-8787\",\n      \"email\": \"iccserra@iccserra.org.br\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Rua Pinheiro Machado, 1707\",\n        \"addressLocality\": \"Caxias do Sul\",\n        \"addressRegion\": \"RS\",\n        \"addressCountry\": \"BR\"\n      },\n      \"sameAs\": \"https://iccserra.org.br\"\n    },\n    \"loanType\": \"Microcrédito Produtivo Orientado\",\n    \"currency\": \"BRL\",\n    \"amount\": {\n      \"@type\": \"MonetaryAmount\",\n      \"minValue\": 600,\n      \"maxValue\": 20000,\n      \"currency\": \"BRL\"\n    },\n    \"areaServed\": {\n      \"@type\": \"State\",\n      \"name\": \"Rio Grande do Sul\"\n    }\n  }', '{\"theme\":\"\",\"nav_label\":\"Produtivo\",\"header_cta\":\"Simular crédito\",\"hero\":{\"pill\":\"Para o MEI e o autônomo da Serra Gaúcha que o banco não quis ouvir\",\"title\":\"Microcrédito produtivo que olha o seu negócio, não só o Serasa\",\"subtitle\":\"A ICC Serra — Banco do Povo — tem agente de crédito que vai até você, conversa com você, e libera de R$ 600 a R$ 20 mil com taxa fixa e parcela que cabe no caixa. Sem IOF. Sem burocracia de banco grande.\",\"cta\":\"Simular meu crédito agora\",\"cta2\":\"\",\"microcopy\":\"Leva 2 minutos. Um agente da sua cidade fala com você em até 24 horas.\",\"img_alt\":\"Empreendedor atendido pelo agente ICC Serra no seu próprio negócio\"},\"trust\":[{\"icon\":\"🏛️\",\"text\":\"OSCIP do Ministério da Justiça\"},{\"icon\":\"📅\",\"text\":\"25 anos no Banco do Povo\"},{\"icon\":\"📍\",\"text\":\"13+ pontos no RS\"},{\"icon\":\"✅\",\"text\":\"Sem IOF\"}],\"pains\":{\"title\":\"Se uma dessas frases já saiu da sua boca, este crédito é pra você:\",\"items\":[\"\\\"O banco nem respondeu meu pedido.\\\"\",\"\\\"Preciso comprar mercadoria pra esse mês, mas o caixa não aguenta.\\\"\",\"\\\"A máquina quebrou. Se eu parar, perco cliente.\\\"\",\"\\\"Não tenho como provar renda — sou autônomo.\\\"\",\"\\\"Se eu botar no cartão, os juros me comem vivo.\\\"\",\"\\\"Eu só quero crescer um pouquinho mais, mas não tem capital.\\\"\"],\"transition\":\"O problema não é o seu negócio. É que banco grande não sabe olhar pra ele. A gente sabe.\",\"cta\":\"Ver quanto posso pegar\"},\"steps\":{\"title\":\"Como funciona o Crédito Olho no Olho\",\"items\":[{\"title\":\"Conta sua ideia\",\"desc\":\"Você preenche um formulário simples — nome, WhatsApp, cidade, o que precisa. Dois minutos e está feito. Nenhum documento nessa hora.\"},{\"title\":\"Agente vai até você\",\"desc\":\"Um agente de crédito da ICC da sua cidade marca a visita. Vai até a sua loja, oficina ou casa. Conversa sobre o negócio, o fluxo de caixa, a finalidade do crédito. É essa análise — feita por um ser humano — que define se o crédito sai.\"},{\"title\":\"Crédito que cabe\",\"desc\":\"Aprovado, o crédito é liberado com parcela ajustada ao que seu caixa aguenta. De R$ 600 a R$ 20 mil, de 3 a 24 meses, taxa fixa de até 3,99% a.m., sem IOF, sem surpresa no boleto.\"}]},\"line\":{\"tag\":\"Microcrédito Produtivo\",\"title\":\"Tudo que você precisa saber antes de solicitar\",\"who_title\":\"Quem pode pedir\",\"who\":[\"MEI formalizado\",\"Trabalhador autônomo (sem CNPJ)\",\"Pequeno empreendedor informal\",\"Microempresa com faturamento compatível\"],\"use_title\":\"Para que serve\",\"use\":[\"Comprar mercadoria ou estoque\",\"Comprar ou consertar máquina e equipamento\",\"Pagar fornecedor e não perder prazo\",\"Ter capital de giro para o mês cheio\",\"Investir em insumos para ampliar a produção\",\"Capital fixo: bancada, geladeira, forno, computador\"],\"use_text\":\"\",\"docs\":[\"RG ou CNH (documento com foto)\",\"CPF\",\"Comprovante de endereço recente\",\"Para MEI: CCMEI (Certificado do Microempreendedor Individual)\",\"Para informal: nota de compra, fotos do negócio ou indicação de cliente\"],\"docs_note\":\"Documentação confirmada com a área de operações antes da publicação. Condições sujeitas a alteração.\",\"prazo\":\"em média 5 a 10 dias úteis após a visita do agente para liberação do crédito.\",\"cond_title\":\"Condições do crédito\",\"cond\":[{\"value\":\"R$ 600 – R$ 20.000\",\"label\":\"Valor disponível\",\"badge\":\"\"},{\"value\":\"3 – 24 meses\",\"label\":\"Prazo de pagamento\",\"badge\":\"\"},{\"value\":\"Até 3,99% a.m.\",\"label\":\"Taxa de juros fixa (56,45% a.a.)\",\"badge\":\"\"},{\"value\":\"Sem IOF\",\"label\":\"Operação isenta de IOF\",\"badge\":\"Diferencial\"},{\"value\":\"Parcela ajustada\",\"label\":\"Calculada no que seu caixa aguenta\",\"badge\":\"\"}],\"cta\":\"Simular meu crédito agora\"},\"proof\":{\"tag\":\"Por que confiar\",\"title\":\"Por que confiar na ICC Serra?\",\"cards\":[{\"icon\":\"🏛️\",\"title\":\"OSCIP qualificada pelo Ministério da Justiça\",\"text\":\"Não somos financeira, não somos agiota. Somos uma instituição comunitária sem fins lucrativos reconhecida pelo governo federal.\"},{\"icon\":\"📅\",\"title\":\"25 anos atendendo na Serra Gaúcha\",\"text\":\"Desde 2001 no Banco do Povo. Quem já foi atendido indica. Quem indica volta.\"},{\"icon\":\"📍\",\"title\":\"13+ pontos de atendimento no RS\",\"text\":\"Caxias do Sul, Bento Gonçalves, Farroupilha, Garibaldi, Vacaria, Veranópolis, Lajeado, Marau e mais. Perto de onde você trabalha.\"},{\"icon\":\"🤝\",\"title\":\"Agente de crédito humano — da sua região\",\"text\":\"Não um app. Não um algoritmo. Uma pessoa que vai até você, conhece o bairro, entende o negócio.\"},{\"icon\":\"🏦\",\"title\":\"Convênio com o BRDE\",\"text\":\"Parceria com o Banco Regional de Desenvolvimento do Extremo Sul para ampliar o acesso ao microcrédito produtivo.\"}],\"testi_title\":\"O que dizem quem já foi atendido\",\"testi\":[{\"text\":\"Peguei o primeiro crédito pra repor o estoque depois do inverno. Deu certo, renovei mais duas vezes. O agente me conhece pelo nome, sabe do meu negócio. Não é banco — é parceiro mesmo.\",\"author\":\"Rodrigo Fiori\",\"meta\":\"Dono de mercearia, MEI — Caxias do Sul\"},{\"text\":\"Trabalho como eletricista autônomo há 12 anos. Achei que banco nenhum ia me atender. O agente da ICC veio na minha casa, viu minha ferragem, conversou comigo. Consegui R$ 4 mil pra comprar material. Valeu muito.\",\"author\":\"Edson Machado\",\"meta\":\"Eletricista autônomo — Bento Gonçalves\"},{\"text\":\"Já renovei três vezes. Comecei com R$ 2 mil pra comprar vasilhame e gás. Hoje atendo 40 marmitas por dia. A parcela sempre coube no meu caixa — nunca deixei de pagar.\",\"author\":\"Simone Bortolini\",\"meta\":\"Vendedora de quentinha — Farroupilha\"}]},\"faq\":{\"title\":\"Perguntas que todo mundo faz antes de solicitar\",\"items\":[{\"q\":\"Não tenho CNPJ. Posso pedir mesmo assim?\",\"a\":\"Sim. A ICC Serra atende MEI formalizado e trabalhadores informais. O que a gente analisa é o seu trabalho real — o negócio que você toca todo dia — não só um papel de registro.\",\"cta\":\"\",\"open\":false},{\"q\":\"Vão consultar o Serasa?\",\"a\":\"A análise considera o histórico de crédito, mas o Serasa não é o único critério. O agente conversa com você, entende a movimentação do negócio e avalia o conjunto. Muita gente com score baixo consegue crédito aqui porque o negócio é sólido.\",\"cta\":\"\",\"open\":false},{\"q\":\"Vou ter que ir lá no escritório várias vezes?\",\"a\":\"Não. Você preenche o formulário agora, em 2 minutos. O agente é que vai até você. A visita acontece na sua loja, oficina ou onde for mais fácil.\",\"cta\":\"Simular meu crédito agora →\",\"open\":false},{\"q\":\"A taxa é muito alta?\",\"a\":\"A taxa máxima é de 3,99% ao mês, fixa, sem IOF. Compara com o cartão de crédito rotativo — que começa em 10% ao mês — ou com cheque especial. A parcela é calculada para caber no seu caixa.\",\"cta\":\"\",\"open\":false},{\"q\":\"A ICC Serra é confiável? É de verdade?\",\"a\":\"É. A ICC Serra existe desde 2001 e é uma OSCIP qualificada pelo Ministério da Justiça — ou seja, uma organização sem fins lucrativos reconhecida pelo governo federal. Tem 13+ pontos físicos no RS e faz parte da rede ABCRED. Você também pode ligar: 54 3217-8787.\",\"cta\":\"\",\"open\":false},{\"q\":\"Quanto tempo demora para o dinheiro cair?\",\"a\":\"Em média 5 a 10 dias úteis depois da visita do agente, dependendo da documentação e da cidade. Nada de meses esperando em fila de banco.\",\"cta\":\"Quero ver meu prazo — simular agora →\",\"open\":false}]},\"final\":{\"title\":\"O Banco do Povo não pergunta o que você tem. Pergunta o que você quer construir.\",\"text\":\"Você tem o negócio, o trabalho e a ideia. A ICC Serra tem o crédito — com agente que vai até você e parcela que cabe no caixa. Sem IOF. Sem ir ao banco. Sem esperar semanas por um não.\\n\\nConta sua ideia. Demora dois minutos.\",\"cta\":\"Solicitar microcrédito produtivo\"},\"legal\":\"Microcrédito produtivo orientado. Taxa de juros: até 3,99% a.m. (56,45% a.a.). Valores: de R$ 600,00 a R$ 20.000,00. Prazo: de 3 a 24 meses. Operação isenta de IOF. Sujeito à análise de crédito. As condições podem variar conforme perfil e finalidade. Consulte o agente da sua cidade.\",\"wa_text\":\"Olá! Quero saber sobre o Microcrédito Produtivo da ICC Serra.\"}', 'images/importadas/microcredito-produtivo-1530297001.jpg', '2026-11-23 23:32:23')
ON DUPLICATE KEY UPDATE `page_title` = VALUES(`page_title`), `page_description` = VALUES(`page_description`), `page_og_image` = VALUES(`page_og_image`), `page_schema` = VALUES(`page_schema`), `page_data` = VALUES(`page_data`), `page_hero_image` = VALUES(`page_hero_image`);

INSERT INTO `ws_gads_lps` (`page_title`, `page_name`, `page_status`, `page_description`, `page_og_image`, `page_schema`, `page_data`, `page_hero_image`, `page_date`) VALUES ('Troca de Cheques Pré-Datados para Pequeno Empresário — ICC Serra', 'troca-de-cheques', '1', 'Antecipe cheques pré-datados com segurança. ICC Serra — Banco do Povo. Para MEI e pequeno empresário na Serra Gaúcha. Agente da sua cidade. Sem IOF.', 'https://iccserra.org.br/assets/og-troca-de-cheques.jpg', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FinancialProduct\",\n    \"name\": \"Troca de Cheques Pré-Datados — ICC Serra\",\n    \"description\": \"Antecipação de cheques pré-datados para MEI e pequeno empresário da Serra Gaúcha. Taxa fixa e transparente. Agente humano.\",\n    \"provider\": {\n      \"@type\": \"Organization\",\n      \"name\": \"ICC Serra — Banco do Povo\",\n      \"url\": \"https://iccserra.org.br\",\n      \"telephone\": \"+55-54-3217-8787\",\n      \"email\": \"iccserra@iccserra.org.br\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Rua Pinheiro Machado, 1707\",\n        \"addressLocality\": \"Caxias do Sul\",\n        \"addressRegion\": \"RS\",\n        \"addressCountry\": \"BR\"\n      }\n    },\n    \"loanType\": \"Antecipação de Recebíveis — Troca de Cheques\",\n    \"currency\": \"BRL\",\n    \"areaServed\": {\n      \"@type\": \"State\",\n      \"name\": \"Rio Grande do Sul\"\n    }\n  }', '{\"theme\":\"\",\"nav_label\":\"Cheque\",\"header_cta\":\"Simular antecipação\",\"hero\":{\"pill\":\"Para o MEI e o pequeno empresário que precisa do dinheiro antes do vencimento\",\"title\":\"Antecipe seus cheques pré-datados com segurança e taxa justa\",\"subtitle\":\"A ICC Serra — Banco do Povo — faz a troca dos seus cheques pré-datados com análise humana, taxa fixa e transparência total. Sem surpresa, sem agiota, sem ir de banco em banco. Um agente da sua cidade resolve.\",\"cta\":\"Falar com um agente agora\",\"cta2\":\"Simular minha antecipação\",\"microcopy\":\"Leva 2 minutos. Um agente da sua cidade fala com você em até 24 horas.\",\"img_alt\":\"Comerciante realizando operação de troca de cheques com a ICC Serra\"},\"trust\":[{\"icon\":\"🏛️\",\"text\":\"OSCIP do Ministério da Justiça\"},{\"icon\":\"🔒\",\"text\":\"Taxa fixa e transparente\"},{\"icon\":\"📅\",\"text\":\"25 anos no Banco do Povo\"},{\"icon\":\"✅\",\"text\":\"Sem IOF\"}],\"pains\":{\"title\":\"Se você está nessa situação agora:\",\"items\":[\"\\\"Recebi cheques pré-datados, mas preciso do dinheiro antes.\\\"\",\"\\\"Tenho cheque de cliente bom, mas o banco não quis descontar.\\\"\",\"\\\"Fui em financeira e a taxa estava absurda.\\\"\",\"\\\"Preciso pagar fornecedor agora, mas o cheque só vence daqui a 60 dias.\\\"\",\"\\\"Não sei como transformar esse cheque em dinheiro de forma segura.\\\"\",\"\\\"Já vi gente perder dinheiro em troca de cheque com desconhecido.\\\"\"],\"transition\":\"Existe um jeito seguro de antecipar seu cheque, com instituição reconhecida, sem taxa de agiota. É aqui.\",\"cta\":\"Quero antecipar meus cheques\"},\"steps\":{\"title\":\"Como funciona a Troca de Cheques na ICC Serra\",\"items\":[{\"title\":\"Conta o que você tem\",\"desc\":\"Você preenche o formulário em 2 minutos — nome, WhatsApp, cidade, quantidade e valor dos cheques que quer antecipar. Sem entregar nada ainda.\"},{\"title\":\"Agente analisa com você\",\"desc\":\"Um agente de crédito da ICC entra em contato, conversa sobre os cheques, verifica as informações e explica as condições — valor que você recebe, desconto aplicado, prazo. Tudo na frente, sem letra miúda.\"},{\"title\":\"Dinheiro na conta, cheque com a ICC\",\"desc\":\"Aprovado, você entrega os cheques para a ICC e recebe o valor antecipado. Taxa fixa, transparente. Sem susto na conta.\"}]},\"line\":{\"tag\":\"Troca de Cheques ICC Serra\",\"title\":\"O que você precisa saber antes de solicitar\",\"who_title\":\"Quem pode solicitar\",\"who\":[\"MEI ou microempresário que recebeu cheques pré-datados de clientes\",\"Pequeno empresário com necessidade de liquidez antes do vencimento\",\"Comércio de bairro, prestador de serviço, feirante que vende parcelado em cheque\"],\"use_title\":\"Como funciona a operação\",\"use\":[],\"use_text\":\"Você tem cheques pré-datados de clientes — recebimentos futuros garantidos no papel. A ICC compra esse recebimento agora, pagando o valor com desconto proporcional ao prazo. Você tem o dinheiro hoje; a ICC fica com o cheque até o vencimento.\",\"docs\":[\"RG ou CNH\",\"CPF\",\"CCMEI (para MEI) ou documento de atividade empresarial\",\"Os cheques a serem antecipados\"],\"docs_note\":\"Limites mínimos e máximos por operação, prazo máximo dos cheques aceitos e demais condições operacionais: consulte o agente da sua cidade. Sujeito à análise.\",\"prazo\":\"após análise e entrega dos cheques ao agente, em média 2 a 5 dias úteis para receber.\",\"cond_title\":\"Por que é seguro aqui\",\"cond\":[{\"value\":\"OSCIP\",\"label\":\"Qualificada pelo Ministério da Justiça\",\"badge\":\"\"},{\"value\":\"Taxa fixa\",\"label\":\"Apresentada antes de assinar qualquer coisa\",\"badge\":\"\"},{\"value\":\"Agente com ID\",\"label\":\"Funcionário identificado da ICC — não um desconhecido\",\"badge\":\"\"},{\"value\":\"Sem IOF\",\"label\":\"Operação isenta de IOF\",\"badge\":\"Diferencial\"},{\"value\":\"25 anos\",\"label\":\"De Banco do Povo na Serra Gaúcha\",\"badge\":\"\"}],\"cta\":\"Falar com um agente agora\"},\"proof\":{\"tag\":\"Por que fazer aqui\",\"title\":\"Por que fazer a troca de cheque aqui, e não em outro lugar?\",\"cards\":[{\"icon\":\"🏛️\",\"title\":\"OSCIP qualificada pelo Ministério da Justiça\",\"text\":\"Não somos financeira de fachada, não somos agiota. Somos uma instituição comunitária sem fins lucrativos, reconhecida pelo governo federal. Transparência total na operação.\"},{\"icon\":\"📅\",\"title\":\"25 anos na Serra Gaúcha — Banco do Povo\",\"text\":\"Desde 2001 atendendo o pequeno empresário. A ICC não some depois da operação — está aqui amanhã, no mês que vem, para a próxima necessidade.\"},{\"icon\":\"🔒\",\"title\":\"Taxa fixa e transparente — sem surpresa\",\"text\":\"Antes de assinar qualquer coisa, o agente mostra exatamente quanto você vai receber e qual é o desconto aplicado. Sem taxa escondida.\"},{\"icon\":\"🤝\",\"title\":\"Agente da sua cidade, atendimento presencial\",\"text\":\"Você entrega os cheques para um agente humano — da ICC, com identificação — não para um desconhecido encontrado na internet.\"},{\"icon\":\"📍\",\"title\":\"13+ pontos no RS\",\"text\":\"Caxias do Sul, Bento Gonçalves, Farroupilha, Garibaldi, Vacaria, Veranópolis, Lajeado, Marau e mais.\"}],\"testi_title\":\"O que dizem quem já usou a linha\",\"testi\":[{\"text\":\"Recebia cheque de 30 dias dos clientes mas precisava pagar fornecedor à vista. A ICC antecipou os cheques sem complicação. Taxa fixa, sem surpresa. Agora uso toda semana — virou parte do meu fluxo de caixa.\",\"author\":\"Gilmar Tomazelli\",\"meta\":\"Dono de distribuidora de bebidas — Lajeado\"},{\"text\":\"Tinha R$ 3 mil em cheque pra receber daqui a 45 dias e não ia conseguir pagar o aluguel. Fui na ICC, na mesma semana anteciparam. Sem burocracia, sem juros absurdos. Me salvou.\",\"author\":\"Sandra Lemos\",\"meta\":\"Costureira, MEI — Estrela\"},{\"text\":\"Meus clientes pagam bastante com cheque pré. Descobri a troca de cheques da ICC há dois anos e nunca mais passei sufoco no fechamento do mês. O agente explicou tudo direitinho, é simples de usar.\",\"author\":\"Luiz Fiorin\",\"meta\":\"Dono de farmácia popular — Encantado\"}]},\"faq\":{\"title\":\"Perguntas antes de solicitar a troca de cheques\",\"items\":[{\"q\":\"E se o cheque do meu cliente não compensar?\",\"a\":\"Esse é o risco que a ICC assume na análise. Por isso o agente verifica as informações antes de fechar a operação. Converse com o agente sobre o perfil dos emitentes dos cheques — isso faz parte da análise.\",\"cta\":\"\",\"open\":true},{\"q\":\"A taxa de desconto vai ser abusiva?\",\"a\":\"Não. A ICC Serra é uma OSCIP, não uma financeira com fins de lucro. A taxa é fixa e apresentada antes da operação — você sabe exatamente o que vai receber antes de entregar qualquer cheque.\",\"cta\":\"\",\"open\":true},{\"q\":\"Preciso ser cliente antigo da ICC para usar essa linha?\",\"a\":\"Não necessariamente. Você pode solicitar mesmo que seja a primeira vez na ICC. O agente vai avaliar as informações e os cheques.\",\"cta\":\"Falar com um agente →\",\"open\":false},{\"q\":\"Posso antecipar cheques de qualquer valor?\",\"a\":\"Há limites mínimos e máximos por operação. Fale com o agente da sua cidade para saber se o volume que você tem se encaixa.\",\"cta\":\"Simular agora →\",\"open\":false},{\"q\":\"A ICC Serra é uma instituição de verdade? Como sei que é seguro?\",\"a\":\"A ICC Serra existe desde 2001 e é uma OSCIP qualificada pelo Ministério da Justiça — reconhecida pelo governo federal. Tem 13+ pontos físicos no RS. Você pode visitar pessoalmente o posto mais perto antes de fazer qualquer operação. Telefone: 54 3217-8787.\",\"cta\":\"\",\"open\":false},{\"q\":\"Banco não quis descontar meus cheques. A ICC consegue?\",\"a\":\"Em muitos casos, sim. A análise da ICC é feita pelo agente, que conhece o contexto local. Muitos cheques recusados pelo banco comercial são aceitos aqui porque a ICC entende a realidade do pequeno empresário da região.\",\"cta\":\"Simular agora →\",\"open\":false}]},\"final\":{\"title\":\"O Banco do Povo não pergunta o que você tem no banco. Pergunta o que você tem em mãos para trabalhar.\",\"text\":\"Você tem cheques de clientes bons — recebimento garantido. O que faltava era transformar isso em capital agora, sem taxa de agiota e sem risco de cair numa operação suspeita. A ICC Serra faz isso com transparência, agente humano e 25 anos de Banco do Povo como garantia.\\n\\nConta o que você tem. Dois minutos.\",\"cta\":\"Solicitar troca de cheques\"},\"legal\":\"Operação de antecipação de recebíveis (cheques pré-datados). Sujeito à análise de crédito e verificação dos instrumentos. Taxa de desconto: fixa, apresentada antes da operação. Operação isenta de IOF. Condições podem variar conforme volume e prazo dos cheques. Consulte o agente da sua cidade. ICC Serra é OSCIP qualificada pelo Ministério da Justiça — CNPJ 05.036.783/0002-68. Nota: revisar com o departamento jurídico a linha legal específica para antecipação de recebíveis antes da publicação.\",\"wa_text\":\"Olá! Quero saber sobre a Troca de Cheques da ICC Serra.\"}', 'images/importadas/troca-de-cheques-1503399086.jpg', '2026-11-23 23:32:23')
ON DUPLICATE KEY UPDATE `page_title` = VALUES(`page_title`), `page_description` = VALUES(`page_description`), `page_og_image` = VALUES(`page_og_image`), `page_schema` = VALUES(`page_schema`), `page_data` = VALUES(`page_data`), `page_hero_image` = VALUES(`page_hero_image`);

